WITH flattened_attrs AS (SELECT id, plan, effective_from, tier_limits, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT id, entry_price, SUM(entry_price) OVER (PARTITION BY plan ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_entry_price, MIN(entry_price) OVER (PARTITION BY plan) AS plan_min_entry_price, LAG(entry_price, 1) OVER (PARTITION BY plan ORDER BY entry_price, id) AS prev_entry_price, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY effective_from DESC, id) AS row_seq FROM flattened_attrs
